# BFS from 8f14e45fce
start = "8f14e45fce"
visited = {start}
depth_map = {start: 0}
queue = deque([start])

while queue:
    current = queue.popleft()
    current_depth = depth_map[current]

    for neighbor in adj[current]:
        if neighbor not in visited:
            visited.add(neighbor)
            depth_map[neighbor] = current_depth + 1
            queue.append(neighbor)

print("Depth map:")
for node, depth in sorted(depth_map.items(), key=lambda x: (x[1], x[0])):
    print(f"Depth {depth}: {node}")

print("\nNodes at depth 4:")
depth_4_nodes = [node for node, depth in depth_map.items() if depth == 4]
print(sorted(depth_4_nodes))
